'use strict';

var constants = require('@toruslabs/constants');
var httpHelpers = require('@toruslabs/http-helpers');
var auth = require('@web3auth/auth');
var log = require('loglevel');
var reactNativeUrlPolyfill = require('react-native-url-polyfill');

function constructURL(params) {
  const {
    baseURL,
    query,
    hash
  } = params;
  const url = new reactNativeUrlPolyfill.URL(baseURL);
  if (query) {
    Object.keys(query).forEach(key => {
      url.searchParams.append(key, query[key]);
    });
  }
  if (hash) {
    const h = new reactNativeUrlPolyfill.URL(constructURL({
      baseURL,
      query: hash
    })).searchParams.toString();
    url.hash = h;
  }
  return url.toString();
}
function getHashQueryParams(url) {
  const result = {};
  const urlObj = new reactNativeUrlPolyfill.URL(url);
  const queryUrlParams = new reactNativeUrlPolyfill.URLSearchParams(urlObj.search.slice(1));
  queryUrlParams.forEach((value, key) => {
    if (key !== "b64Params") {
      result[key] = value;
    }
  });
  const queryResult = queryUrlParams.get("b64Params");
  if (queryResult) {
    try {
      const queryParams = JSON.parse(auth.safeatob(queryResult));
      Object.keys(queryParams).forEach(key => {
        result[key] = queryParams[key];
      });
    } catch (error) {
      log.error(error);
    }
  }
  const hashUrlParams = new reactNativeUrlPolyfill.URLSearchParams(urlObj.hash.substring(1));
  hashUrlParams.forEach((value, key) => {
    if (key !== "b64Params") {
      result[key] = value;
    }
  });
  const hashResult = hashUrlParams.get("b64Params");
  if (hashResult) {
    try {
      const hashParams = JSON.parse(auth.safeatob(hashResult));
      Object.keys(hashParams).forEach(key => {
        result[key] = hashParams[key];
      });
    } catch (error) {
      log.error(error);
    }
  }
  return result;
}
const signerHost = web3AuthNetwork => {
  return constants.SIGNER_MAP[web3AuthNetwork !== null && web3AuthNetwork !== void 0 ? web3AuthNetwork : auth.WEB3AUTH_NETWORK.SAPPHIRE_MAINNET];
};
const fetchProjectConfig = async (clientId, web3AuthNetwork) => {
  try {
    const url = new reactNativeUrlPolyfill.URL(`${signerHost(web3AuthNetwork)}/api/configuration`);
    url.searchParams.append("project_id", clientId);
    url.searchParams.append("network", web3AuthNetwork);
    url.searchParams.append("whitelist", "true");
    //log.debug("Fetching project configuration from URL:", url.href);
    const res = await httpHelpers.get(url.href);
    //log.debug(`[Web3Auth] config response: ${JSON.stringify(res)}`);
    return res;
  } catch (e) {
    throw new Error(`Failed to fetch project config: ${e.message}`);
  }
};

exports.constructURL = constructURL;
exports.fetchProjectConfig = fetchProjectConfig;
exports.getHashQueryParams = getHashQueryParams;
exports.signerHost = signerHost;
